const { useState } = React;

const FormField = ({ label, children, helperText }) => (
    <div className="form-field">
        <label>{label}</label>
        {children}
        {helperText && <span className="helper-text">{helperText}</span>}
    </div>
);

const SupportContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        alert(`Thank you, ${formData.fullName}! Your support request has been submitted.`);
        console.log('Form submitted:', formData);
    };

    return (
        <div className="support-container">
            <h1>Support Request</h1>
            <form onSubmit={handleSubmit}>
                <FormField label="Full Name">
                    <input
                        type="text"
                        name="fullName"
                        value={formData.fullName}
                        onChange={handleChange}
                        required
                        placeholder="John Doe"
                    />
                </FormField>

                <FormField label="Email Address">
                    <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        placeholder="john@example.com"
                    />
                </FormField>

                <FormField 
                    label="Phone Number (Optional)" 
                    helperText="Expected format: +1 (555) 000-0000"
                >
                    <input
                        type="tel"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        placeholder="+1 (555) 000-0000"
                    />
                </FormField>

                <button type="submit">Submit Request</button>
            </form>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<SupportContactForm />);

