h1 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    text-align: center;
    font-weight: 300;
}

.form-field {
    margin-bottom: 1.5rem;
    display: flex;
    flex-direction: column;
}

.form-field label {
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    font-weight: 500;
}

.form-field input {
    background-color: var(--input-bg);
    border: 1px solid var(--input-border);
    border-radius: 6px;
    color: var(--text-color);
    padding: 0.75rem;
    font-size: 1rem;
    transition: border-color 0.2s;
}

.form-field input:focus {
    outline: none;
    border-color: var(--accent-color);
}

.helper-text {
    font-size: 0.8rem;
    color: var(--helper-text);
    margin-top: 0.4rem;
}

button {
    background-color: var(--accent-color);
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.75rem;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s;
    margin-top: 1rem;
}

button:hover {
    background-color: var(--accent-hover);
}

button:active {
    transform: translateY(1px);
}

.success-message {
    text-align: center;
}

.success-message h1 {
    color: var(--accent-color);
}

.success-message p {
    margin-bottom: 2rem;
    line-height: 1.5;
}
